import {calculate,exportCSV,summaryCSV} from './core.js';import {catalogs} from './locales.js';
const lang=document.documentElement.lang,c=catalogs[lang]||catalogs.ko,$=id=>document.getElementById(id),number=new Intl.NumberFormat(lang,{minimumFractionDigits:2,maximumFractionDigits:2});let result=null;
document.title=c.title;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=c[el.dataset.i18n]);document.querySelector('.languages').setAttribute('aria-label',c.language);document.querySelector(`[data-lang="${lang}"]`).setAttribute('aria-current','page');
function status(s,error=false){$('status').textContent=s;$('status').classList.toggle('error',error);}
function invalidate(){result=null;document.querySelectorAll('[data-export]').forEach(b=>b.disabled=true);['total','decimal','breakTotal','rowCount'].forEach(id=>$(id).textContent='—');$('dailyRows').replaceChildren();$('weeklyRows').replaceChildren();status(c.stale);}
function addRow(r={date:'2026-10-26',start:'09:00',end:'18:00',break:'60',nextDay:false}){
 if($('records').children.length>=200){status(c.errors.limit,true);return;}const tr=document.createElement('tr');
 for(const [key,type,text] of [['date','date',c.date],['start','time',c.start],['end','time',c.end],['nextDay','checkbox',c.next],['break','number',c.pause]]){const td=document.createElement('td'),input=document.createElement('input');td.dataset.label=text;input.type=type;input.dataset.key=key;input.setAttribute('aria-label',text);if(type==='checkbox')input.checked=r[key];else input.value=r[key];if(type==='number'){input.min=0;input.max=1440;input.step=1;}if(type==='date'){input.min='1900-01-01';input.max='2100-12-31';}input.addEventListener('input',invalidate);input.addEventListener('change',invalidate);td.append(input);tr.append(td);}
 const td=document.createElement('td'),button=document.createElement('button');button.type='button';button.className='delete';button.textContent=c.remove;button.onclick=()=>{tr.remove();invalidate();};td.append(button);tr.append(td);$('records').append(tr);invalidate();
}
function read(){return [...$('records').children].map(tr=>Object.fromEntries([...tr.querySelectorAll('input')].map(i=>[i.dataset.key,i.type==='checkbox'?i.checked:i.value])));}
function duration(m){return `${Math.floor(m/60)} ${c.hours} ${m%60} ${c.minutes}`;}
function table(body,data){$(body).replaceChildren();for(const [date,m] of data){const tr=document.createElement('tr');for(const value of [date,duration(m),number.format(m/60)]){const td=document.createElement('td');td.textContent=value;tr.append(td);}$(body).append(tr);}}
function run(){invalidate();try{result=calculate(read());$('total').textContent=duration(result.net);$('decimal').textContent=number.format(result.net/60);$('breakTotal').textContent=`${result.pause} ${c.minutes}`;$('rowCount').textContent=String(result.rows.length);table('dailyRows',result.daily);table('weeklyRows',result.weekly);document.querySelectorAll('[data-export]').forEach(b=>b.disabled=false);status(c.ready.replace('{n}',result.rows.length));}catch(e){status((c.errors[e.code]||c.errors.unknown)+(e.detail||''),true);}}
function example(){$('records').replaceChildren();[{date:'2026-10-26',start:'09:00',end:'18:00',break:'60',nextDay:false},{date:'2026-10-27',start:'22:00',end:'06:30',break:'30',nextDay:true},{date:'2026-11-02',start:'09:15',end:'13:00',break:'15',nextDay:false}].forEach(addRow);run();}
function save(text,name){const u=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);status(c.saved);}
$('add').onclick=()=>{const last=$('records').lastElementChild;let date=last?.querySelector('[data-key=date]').value||'2026-10-26';addRow({date,start:'09:00',end:'18:00',break:'60',nextDay:false});};$('example').onclick=example;$('calculate').onclick=run;
$('recordCsv').onclick=()=>{if(result)save(exportCSV(result,[c.date,c.start,c.end,c.next,c.pause,c.elapsed,c.net,c.decimal,c.week],c.yes,c.no),'timesheet-records.csv');};
$('summaryCsv').onclick=()=>{if(result)save(summaryCSV(result,[c.kind,c.dateKey,c.net,c.decimal],c.daily,c.weekly),'timesheet-totals.csv');};
$('copy').onclick=async()=>{if(!result)return;try{await navigator.clipboard.writeText(`${c.total}: ${duration(result.net)}\n${c.decimal}: ${number.format(result.net/60)}\n${c.breakTotal}: ${result.pause} ${c.minutes}`);status(c.copied);}catch{status(c.copyError,true);}};
example();
